<script setup lang="ts">
const {register,load}=useAuth();const name=ref(''),email=ref(''),password=ref(''),confirm=ref(''),loading=ref(false),error=ref('');onMounted(async()=>{if(await load())navigateTo('/profile')});async function submit(){if(password.value!==confirm.value){error.value='Les mots de passe ne correspondent pas';return}loading.value=true;error.value='';try{await register(name.value,email.value,password.value);await navigateTo('/profile')}catch(e:any){error.value=e?.data?.statusMessage||'Inscription impossible'}finally{loading.value=false}};useSeoMeta({title:'Créer un compte'})
</script>
<template><main class="auth-page page-top"><section class="auth-card"><p class="eyebrow">NOUVEAU COMPTE</p><h1>Votre cinéma vous suit.</h1><p>Créez un compte pour retrouver vos données sur chaque session.</p><form @submit.prevent="submit"><label>Nom affiché<input v-model="name" autocomplete="name" minlength="2" required></label><label>Email<input v-model="email" type="email" autocomplete="email" required></label><label>Mot de passe<input v-model="password" type="password" autocomplete="new-password" minlength="10" required></label><label>Confirmation<input v-model="confirm" type="password" autocomplete="new-password" required></label><p v-if="error" class="auth-error">{{ error }}</p><button class="btn btn--primary" :disabled="loading">{{ loading?'Création…':'Créer mon compte' }}</button></form><p>Déjà inscrit ? <NuxtLink to="/login">Se connecter</NuxtLink></p></section></main></template>
